  1	using System;
  2	using CommunityToolkit.Mvvm.ComponentModel;
  3	
  4	namespace LoadOrderKeeper.ViewTexts
  5	{
  6	    /// <summary>
  7	    /// Text ViewModel for DiffDialog. Exposes all localized strings consumed by
  8	    /// <c>DiffWindow.xaml</c> as <see cref="string"/> properties backed by
  9	    /// <see cref="LocalizationService"/>.
 10	    /// </summary>
 11	    /// <remarks>
 12	    /// <para><b>CultureChanged subscription model</b><br/>
 13	    /// The constructor subscribes <c>OnCultureChanged</c> to
 14	    /// <c>LocalizationService.CultureChanged</c>. When the user switches language
 15	    /// at runtime, <c>OnCultureChanged</c> raises <c>INotifyPropertyChanged</c>
 16	    /// for every property so that all bound UI elements re-read their string values
 17	    /// without requiring a window reload.</para>
 18	    ///
 19	    /// <para><b>RefreshAll()</b><br/>
 20	    /// <c>RefreshAll()</c> is a public wrapper that calls <c>OnCultureChanged</c>
 21	    /// with dummy arguments. It exists for legacy compatibility with call sites that
 22	    /// trigger a bulk refresh outside of a real culture-change event (e.g. after a
 23	    /// programmatic locale reset in tests). New code should rely on the
 24	    /// <c>CultureChanged</c> event instead.</para>
 25	    ///
 26	    /// <para><b>Locale-key-to-property naming convention</b><br/>
 27	    /// Each property maps 1-to-1 to a key in the <c>"DiffDialog"</c> section of
 28	    /// the locale JSON files. The property name is identical to the locale key
 29	    /// (e.g., property <c>GuidanceSidebarTitle</c> reads key
