349	        private int ComputeScrollTargetIndex()
350	        {
351	            if (DiffLines.Count == 0)
352	            {
353	                return -1;
354	            }
355	
356	            if (!ShowAllMods)
357	            {
358	                return HasDifferences ? 0 : -1;
359	            }
360	
361	            if (HasDifferences)
362	            {
363	                for (int index = 0; index < DiffLines.Count; index++)
364	                {
365	                    if (DiffLines[index].ChangeType != DiffChangeType.Unchanged && DiffLines[index].ChangeType != DiffChangeType.Separator)
366	                    {
367	                        return index;
368	                    }
369	                }
370	            }
371	
372	            return DiffLines.Count - 1;
373	        }
