427	            int maxNumber = list.Count > 0
428	                ? list.Max(l => l.ReferenceNumber ?? l.CurrentNumber ?? 0)
429	                : 0;
430	            int width = Math.Max(3, maxNumber.ToString().Length);
431	            string format = new string('0', width);
432	
433	            foreach (var line in list)
434	            {
435	                int? displayNumber = line.ReferenceNumber ?? line.CurrentNumber;
436	                line.FormattedLineNumber = displayNumber.HasValue
437	                    ? displayNumber.Value.ToString(format)
438	                    : string.Empty;
439	            }
440	        }
