470	        public async Task<bool> RefreshDiffAsync(string? reason = null)
471	        {
472	            if (_isRefreshing)
473	            {
474	                return false;
475	            }
476	
477	            _isRefreshing = true;
478	            try
479	            {
480	                var trimmedLines = await DiffService.GetPluginsDiffAsync(_mainViewModel.Config);
481	                string newSignature = BuildSignature(trimmedLines);
482	
483	                bool signatureChanged = !string.Equals(newSignature, _lastDiffSignature, StringComparison.Ordinal);
484	                
485	                if (signatureChanged)
486	                {
487	                    var fullLines = await DiffService.GetFullPluginsDiffAsync(_mainViewModel.Config);
488	                    ReplaceDiffLines(fullLines);
489	                    _lastDiffSignature = newSignature;
490	                    DiffStatusMessage = reason ?? Texts.DifferencesLoadedStatus;
491	                    RequestScroll();
492	                }
493	                else
494	                {
495	                    DiffStatusMessage = Texts.NoNewDifferencesStatus;
496	                }
497	
498	                return signatureChanged;
499	            }
500	            catch (Exception ex)
501	            {
502	                DiffStatusMessage = Texts.FailedToRefreshError + " " + ex.Message;
503	                return false;
504	            }
505	            finally
506	            {
507	                _isRefreshing = false;
508	            }
509	        }
