511	        [RelayCommand]
512	        private async Task DiscardChangesAsync()
513	        {
514	            if (!HasDifferences)
515	            {
516	                DiffStatusMessage = Texts.NoDifferencesToDiscardStatus;
517	                return;
518	            }
519	
520	            var discardCommand = _mainViewModel.DiscardChangesCommand;
521	            if (discardCommand is null || !discardCommand.CanExecute(null))
522	            {
523	                DiffStatusMessage = Texts.CannotDiscardNowStatus;
524	                return;
525	            }
526	
527	            // Request confirmation from the view
528	            var eventArgs = new ConfirmationRequestedEventArgs(
529	                Texts.ConfirmDiscardTitle, 
530	                Texts.ConfirmDiscardMessage,
